import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第四册：流利英语 · Lesson 28 Patients and doctors","description":"学习 间接问句与疑问语序，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 28 Patients and doctors","description":"学习 间接问句与疑问语序，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 间接问句与疑问语序，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 27 The 'Vasa'","link":"/life/english/new-concept/book-4/unit-04/lesson-027"},"next":{"text":"第四册：流利英语 · Lesson 29 The hovercraft","link":"/life/english/new-concept/book-4/unit-04/lesson-029"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 27 The 'Vasa'","link":"/life/english/new-concept/book-4/unit-04/lesson-027"},"next":{"text":"第四册：流利英语 · Lesson 29 The hovercraft","link":"/life/english/new-concept/book-4/unit-04/lesson-029"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-028.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-028.md"}`),i={name:"life/english/new-concept/book-4/unit-04/lesson-028.md"};function l(s,e,r,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-28-patients-and-doctors" tabindex="-1">第四册：流利英语 · Lesson 28 Patients and doctors <a class="header-anchor" href="#第四册-流利英语-·-lesson-28-patients-and-doctors" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 28 Patients and doctors&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕患者与医生的交流阅读社会观察，关注双方掌握的信息不同如何影响理解。训练用礼貌且明确的问题核实对方意思，不从历史文章推导具体诊疗结论。重点是间接问句与陈述语序，让咨询更自然，同时保持问题范围和时间指向清楚。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>consultation</td><td>/ˌkɒnsəlˈteɪʃən/</td><td>n.</td><td>咨询；问诊</td><td>a brief consultation</td></tr><tr><td>clarify</td><td>/ˈklærɪfaɪ/</td><td>v.</td><td>澄清</td><td>clarify a point</td></tr><tr><td>concern</td><td>/kənˈsɜːn/</td><td>n.</td><td>担忧</td><td>raise a concern</td></tr><tr><td>explanation</td><td>/ˌekspləˈneɪʃən/</td><td>n.</td><td>解释</td><td>a clear explanation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>in plain language — 用浅显语言</li><li>make sure — 确认某事</li></ul><h2 id="语法讲解-间接问句与疑问语序" tabindex="-1">语法讲解：间接问句与疑问语序 <a class="header-anchor" href="#语法讲解-间接问句与疑问语序" aria-label="Permalink to &quot;语法讲解：间接问句与疑问语序&quot;">​</a></h2><p>Could you explain what the term means? 中 what 从句是 explain 的宾语，使用 the term means 的陈述语序，不保留直接问句 What does the term mean? 的 does。yes/no 问题可用 whether 或 if 引入。礼貌框架 Could you tell me 不会自动把从句变成过去时；从句时态应由所问内容决定。避免把礼貌间接问句写成多个问号或重复助动词。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Could you explain what this term means in plain language?</p></blockquote><p>您能用浅显的语言解释这个术语的含义吗？</p><p>Could you explain 是礼貌主句；what this term means 为宾语从句，this term 在 means 前。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Could you explain what does this term mean? 错用直接问句语序；应去 does 并用 means。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 Could you explain 时自然连读；把 what this term means 读成完整陈述式节奏，避免在 means 前插入 does。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Could you explain what this term means? I want to make sure I have understood your explanation correctly. Would it be possible to have the main points in writing?</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句就诊沟通练习，仅询问信息表达：术语含义、理解核对、书面说明。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>问题集中在沟通与理解，使用礼貌框架，不替专业人员提供诊疗结论。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>把 When does the appointment begin? 放入 Could you tell me…?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Could you tell me when the appointment begins?</p><p><strong>解析：</strong> 间接问句使用陈述语序，begins 随单数主语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中的 could 表过去发生的解释吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不表示。</p><p><strong>解析：</strong> 此处用于礼貌请求。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：I would like to know ___ another appointment is needed.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whether 或 if</p><p><strong>解析：</strong> 是非疑问可以用 whether/if 引入。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：间接问句与疑问语序。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-027">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-029">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
